    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Diario Official - 1891</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400&family=Special+Elite&family=Times+New+Roman&display=swap');

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: #f2ebd9;
